var pipeline = {
    async divide(a, b) {
        if (b === 0) {
            throw new Error('Synthetic denominator is zero')
        }
        return a / b
    },
    async rotate(text) {
        const units = Array.from(text)
        return units.slice(1).join('') + units[0]
    },
    async transform(text, mode) {
        if (mode === 0) {
            return text.toUpperCase()
        }
        if (mode === 1) {
            return text.toLowerCase()
        }
        return Array.from(text).reverse().join('')
    }
}

